import { useState, useCallback, useMemo, useEffect } from 'react';
import Alert from '@mui/material/Alert';
import Box from '@mui/material/Box';
import CircularProgress from '@mui/material/CircularProgress';
import EditForm from '../../components/profile/EditForm';
import PageContainer from '../../components/PageContainer';
import { toast } from 'react-toastify';
import { EditValidation } from '../../validation/ProfileValidation';
import Divider from '@mui/material/Divider';
import { useNavigate, useParams } from 'react-router-dom';
import { getDetails, updateProfile } from '../../api/ProfileApi';
import { getSettings, updateSetting } from '../../api/SettingApi';
import SettingsForm from '../../components/settings/SettingsForm';

function SettingEditForm({ initialValues, onSubmit }) {
    const navigate = useNavigate();

    const [formState, setFormState] = useState(() => ({
        values: initialValues,
        errors: {},
    }));
    const formValues = formState.values;
    const formErrors = formState.errors;

    const setFormValues = useCallback((newFormValues) => {
        setFormState((previousState) => ({
            ...previousState,
            values: newFormValues,
        }));
    }, []);

    useEffect(() => {
        if (initialValues) {
            setFormState({
                values: {
                    ...initialValues,
                },
                errors: {}
            })
        }
    }, [initialValues])

    const setFormErrors = useCallback((newFormErrors) => {
        setFormState((previousState) => ({
            ...previousState,
            errors: newFormErrors,
        }));
    }, []);

    const handleFormFieldChange = useCallback(
        (name, value) => {

            const newItems = Object.values(formValues).map(item => {
                if (item.key == name) {
                    return { ...item, value }
                }
                return item;
            })

            const newFormValues = { ...newItems };

            setFormValues(newFormValues);

            const { issues } = EditValidation(newFormValues);

            setFormErrors({
                ...formErrors,
                [name]: issues?.find(i => i.path?.[0] === name)?.message,
            });

        },
        [formValues, setFormValues, formErrors],
    );

    const handleFormReset = useCallback(() => {
        setFormValues(initialValues);
    }, [initialValues, setFormValues]);

    const handleFormSubmit = useCallback(async () => {

        // const { issues } = EditValidation(formValues);

        // if (issues && issues.length > 0) {
        //     setFormErrors(
        //         Object.fromEntries(issues.map((issue) => [issue.path?.[0], issue.message])),
        //     );
        //     return;
        // }
        // setFormErrors({});

        try {
            await onSubmit(formValues);
            toast.success("ویرایش با موفقیت انجام شد.")

        } catch (editError) {
            toast.error("مشکلی در گرفتن اطلاعات رخ داده است")
        }
    }, [formValues, navigate, onSubmit, setFormErrors]);

    return (
        <SettingsForm
            formState={formState}
            onFieldChange={handleFormFieldChange}
            onSubmit={handleFormSubmit}
            onReset={handleFormReset}
            submitButtonLabel="ذخیره"
        />
    );
}

export default function Setting() {
    const [settings, setSettings] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    const [error, setError] = useState(null);

    const loadData = useCallback(async () => {
        setError(null);
        setIsLoading(true);

        getSettings()
            .then(data => {
                setSettings(data.data.data)

                setIsLoading(false);
            }).catch(err => { })

        setIsLoading(false);
    }, [setSettings]);

    useEffect(() => {
        loadData();
    }, [loadData]);

    const handleSubmit = useCallback(

        async (formValues) => {
            updateSetting(formValues)
                .then(data => {
                    setSettings(data.data.data)
                    setIsLoading(false);
                }).catch(err => { })
        },
        [settings],
    );

    const renderEdit = useMemo(() => {
        if (isLoading) {
            return (
                <Box
                    sx={{
                        flex: 1,
                        display: 'flex',
                        flexDirection: 'column',
                        alignItems: 'center',
                        justifyContent: 'center',
                        width: '100%',
                        m: 1,
                    }}
                >
                    <CircularProgress />
                </Box>
            );
        }
        if (error) {
            return (
                <Box sx={{ flexGrow: 1 }}>
                    <Alert severity="error">{error.message}</Alert>
                </Box>
            );
        }

        return settings ? (
            <SettingEditForm initialValues={settings} onSubmit={handleSubmit} />
        ) : null;
    }, [isLoading, error, settings, handleSubmit]);


    return (
        <PageContainer
            title={"تنظیمات کلی"}
        >
            <Divider sx={{ marginBottom: "4%" }} />
            <Box sx={{ display: 'flex', flex: 1 }}>{renderEdit}</Box>
        </PageContainer>
    );
}
