import Box from '@mui/material/Box';
import Button from '@mui/material/Button';
import Stack from '@mui/material/Stack';
import { DataGrid, GridActionsCellItem, gridClasses } from '@mui/x-data-grid';
import AddIcon from '@mui/icons-material/Add';
import VpnKeyOutlined from '@mui/icons-material/VpnKeyOutlined';
import History from '@mui/icons-material/History';
import EditIcon from '@mui/icons-material/Edit';
import DeleteIcon from '@mui/icons-material/Delete';
import { useLocation, useNavigate, useSearchParams } from 'react-router';
import { useDialogs } from '../../hooks/useDialogs/useDialogs';
import PageContainer from '../../components/PageContainer';
import { toast } from 'react-toastify';
import { getUsers, deleteUser } from '../../api/UserApi';
import { APP_ROUTES } from '../../utlis/constants/routePath';
import { useCallback, useEffect, useMemo, useState } from 'react';
import useAuth from '../../hooks/useAuth/useAuth';
import { PERMISSION } from '../../utlis/constants/Permissions';

const INITIAL_PAGE_SIZE = 10;
const style = {
  position: 'absolute',
  top: '50%',
  left: '50%',
  transform: 'translate(-50%, -50%)',
  width: 400,
  bgcolor: 'background.paper',
  border: '2px solid #000',
  boxShadow: 24,
  p: 4,
};
export default function UserList() {
  const { pathname } = useLocation();
  const [searchParams] = useSearchParams();
  const { hasPermission } = useAuth();

  const navigate = useNavigate();

  const dialogs = useDialogs();

  const [paginationModel, setPaginationModel] = useState({
    page: searchParams.get('page') ? Number(searchParams.get('page')) : 0,
    pageSize: searchParams.get('pageSize')
      ? Number(searchParams.get('pageSize'))
      : INITIAL_PAGE_SIZE,
  });
  const [filterModel, setFilterModel] = useState(
    searchParams.get('filter')
      ? JSON.parse(searchParams.get('filter') ?? '')
      : { items: [] },
  );
  const [sortModel, setSortModel] = useState(
    searchParams.get('sort') ? JSON.parse(searchParams.get('sort') ?? '') : [],
  );

  const [users, setUsers] = useState([]);

  const [isLoading, setIsLoading] = useState(true);
  const [permissions, setPermissions] = useState([]);

  const handlePaginationModelChange = useCallback(
    (model) => {
      setPaginationModel(model);

      searchParams.set('page', String(model.page));
      searchParams.set('pageSize', String(model.pageSize));

      const newSearchParamsString = searchParams.toString();

      navigate(
        `${pathname}${newSearchParamsString ? '?' : ''}${newSearchParamsString}`,
      );
    },
    [navigate, pathname, searchParams],
  );

  const handleFilterModelChange = useCallback(
    (model) => {
      setFilterModel(model);

      if (
        model.items.length > 0 ||
        (model.quickFilterValues && model.quickFilterValues.length > 0)
      ) {
        searchParams.set('filter', JSON.stringify(model));
      } else {
        searchParams.delete('filter');
      }

      const newSearchParamsString = searchParams.toString();

      navigate(
        `${pathname}${newSearchParamsString ? '?' : ''}${newSearchParamsString}`,
      );
    },
    [navigate, pathname, searchParams],
  );

  const handleSortModelChange = useCallback(
    (model) => {
      setSortModel(model);

      if (model.length > 0) {
        searchParams.set('sort', JSON.stringify(model));
      } else {
        searchParams.delete('sort');
      }

      const newSearchParamsString = searchParams.toString();

      navigate(
        `${pathname}${newSearchParamsString ? '?' : ''}${newSearchParamsString}`,
      );
    },
    [navigate, pathname, searchParams],
  );

  const loadData = useCallback(async () => {
    setIsLoading(true);

    const request = {
      'userId': searchParams.get("userId")
    }
    getUsers(request)
      .then(data => {
        setUsers(data.data.data)

        setIsLoading(false)

      }).catch(() => { 
        //toast.error("عدم دسترسی") 
      })

    setIsLoading(false);
  }, [paginationModel, sortModel, filterModel, searchParams]);

  useEffect(() => {
    loadData();
  }, [loadData]);


  const handleCreateClick = useCallback(() => {
    navigate(APP_ROUTES.USER_CREATE_PATH);
  }, [navigate]);

  const handleUserEditPage = useCallback(
    (userID) => () => {
      navigate(`/user/edit/${userID}`);
    },
    [navigate],
  );
  const handelPermissions = useCallback(

    (userID) => () => {
      navigate(`/user/assignPermission/${userID}`);
    },
    [navigate],
  );

  const handleInventoryHistoty = useCallback(
    (userID) => () => {
      navigate(APP_ROUTES.HISTORY_LIST_PATH + `?entityId=${userID}&entityName=Users`)
    }, [navigate]
  )
  const handelDeleteUser = useCallback(
    (user) => async () => {

      const confirmed = await dialogs.confirm(
        `آبا از حذف کاربر  ${user.username} مطمئنید?`,
        {
          title: `حذف کاربر?`,
          severity: 'خطا',
          okText: 'حذف',
          cancelText: 'انصراف',
        },
      );

      if (confirmed) {
        setIsLoading(true);

        deleteUser(user.id)
          .then(() => {
            loadData();
            toast.success("کاربر با موفقیت حذف شد.")
            setIsLoading(false)

          }).catch(() =>
            toast.error("مشکلی در گرفتن اطلاعات رخ داده است")
          )
        setIsLoading(false);
      }
    },
    [dialogs, loadData],
  );

  const initialState = useMemo(
    () => ({
      pagination: { paginationModel: { pageSize: INITIAL_PAGE_SIZE } },
    }),
    [],
  );

  const isAlow = hasPermission([PERMISSION.USER_EDIT, PERMISSION.USER_DELETE, PERMISSION.USER_ADD_PERMISSION, PERMISSION.USER_HISTORY]);

  const columns = useMemo(
    () => [
      { field: 'username', headerName: 'نام کاربری', width: 240 },
      { field: 'mobile', headerName: 'موبایل', width: 140 },
      { field: 'email', headerName: 'ایمیل', width: 240 },
      { field: 'role', headerName: 'نقش', width: 140 },
      {
        field: 'status',
        headerName: 'وضعیت',
        width: 140,
        type: 'string',
        renderCell: params => params.row.status == 'Active' ? 'فعال' : 'غیرفعال'
      },
      ...(isAlow ? [{
        field: '',
        headerName: 'عملیات',
        type: 'actions',
        flex: 1,
        align: 'center',
        getActions: ({ row }) => {
          const actions = [];
          if (hasPermission([PERMISSION.USER_EDIT])) {
            actions.push(<GridActionsCellItem
              key="edit-item"
              icon={<EditIcon />}
              label="Edit"
              onClick={handleUserEditPage(row.id)}
            />)
          }

          if (hasPermission([PERMISSION.USER_DELETE])) {
            actions.push(<GridActionsCellItem
              key="delete-item"
              icon={<DeleteIcon />}
              label="Delete"
              onClick={handelDeleteUser(row)}
            />)
          }
          if (hasPermission([PERMISSION.USER_ADD_PERMISSION])) {
            actions.push(<GridActionsCellItem
              key="permission-item"
              icon={<VpnKeyOutlined />}
              label="permissions"
              onClick={handelPermissions(row.id)}
            />)
          }
          if (hasPermission([PERMISSION.USER_HISTORY])) {
            actions.push(<GridActionsCellItem
              key="log-item"
              icon={<History />}
              label="log"
              onClick={handleInventoryHistoty(row.id)}
            />)
          }
          return actions;
        }
      },] : [])
    ],
    [handleUserEditPage, handelDeleteUser],
  );

  const pageTitle = 'کاربران';

  return (

    <PageContainer
      title={pageTitle}
      marginTop='20px'
      actions={hasPermission([PERMISSION.USER_CREATE]) &&
        (<Stack direction="row" alignItems="center" spacing={1}>
          <Button
            variant="contained"
            onClick={handleCreateClick}
            startIcon={<AddIcon />}
          >
            افزودن کاربر
          </Button>
        </Stack>)
      }
    >

      <Box sx={{ width: '100%', marginTop: '5px', paddingRight: '5px' }}>

        <DataGrid
          rows={users}
          rowCount={users.length}
          columns={columns}
          align="center"
          pagination
          // sortingMode="server"
          // filterMode="server"
          // paginationMode="server"
          paginationModel={paginationModel}
          onPaginationModelChange={handlePaginationModelChange}
          sortModel={sortModel}
          onSortModelChange={handleSortModelChange}
          filterModel={filterModel}
          onFilterModelChange={handleFilterModelChange}
          disableRowSelectionOnClick
          loading={isLoading}
          initialState={initialState}
          showToolbar
          localeText={{ noRowsLabel: "موردی یافت نشد" }}
          pageSizeOptions={[5, INITIAL_PAGE_SIZE, 25]}
          sx={{
            [`& .${gridClasses.columnHeader}, & .${gridClasses.cell}`]: {
              outline: 'transparent',
            },
            [`& .${gridClasses.columnHeader}:focus-within, & .${gridClasses.cell}:focus-within`]:
            {
              outline: 'none',
            },
            [`& .${gridClasses.row}:hover`]: {
              cursor: 'pointer',
            },
          }}
          slotProps={{
            loadingOverlay: {
              variant: 'circular-progress',
              noRowsVariant: 'circular-progress',
            },
            baseIconButton: {
              size: 'small',
            },
          }}
        />
      </Box>
      {/* {
        open && (<AddPermissionForm open={open} close={handleClose} allPermissions={permissions} />)
      } */}


    </PageContainer>
  );
}
