import Api from "./Api"

export const getInventories = (equipment = "ALL") => {
    return Api.get(`/inventory?equipment=${equipment}`);
}
export const deleteInventory = (inventoryID) => {
    return Api.delete(`/inventory/${inventoryID}`)
}

export const InventoryDetails = (inventoryID) => {
    return Api.get(`/inventory/${inventoryID}`)
}
export const createInventory = (data) => {
    return Api.post('/inventory', data)
}

export const updateInventory = (data) => {
    return Api.put('/inventory', data)
}

export const addDuplicateInventory = (data) => {
    return Api.post('/inventory/addDuplicate', data)
}

export const getExternalEquipmentInventories = (equipmentID) => {
    return Api.post(`/equipment/inventory/externalType?equipmentId=${equipmentID}`)
}